// Generic helper — pass command and optional payload
async function customerCommand(customerId, command, payload = {}) {
  const res = await fetch(
    `{{base_url}}/api/v1/customers/${customerId}?command=${command}`,
    {
      method: 'POST',
      headers: {
        'Authorization': 'Bearer {{access_token}}',
        'Content-Type': 'application/json',
        'X-Tenant-ID': '{{tenant_id}}'
      },
      body: JSON.stringify(payload)
    }
  );
  return res.json();
}

// Examples:
await customerCommand('{{customerId}}', 'activate');
await customerCommand('{{customerId}}', 'reject', { reason: 'Insufficient docs' });
await customerCommand('{{customerId}}', 'assignStaff', { staffId: 'uuid' });
await customerCommand('{{customerId}}', 'proposeTransfer', { destinationOfficeId: 'uuid', transferDate: '2024-06-01' });

import requests

def customer_command(customer_id, command, payload=None):
    return requests.post(
        f'{{base_url}}/api/v1/customers/{customer_id}',
        params={'command': command},
        headers={
            'Authorization': 'Bearer {{access_token}}',
            'X-Tenant-ID': '{{tenant_id}}'
        },
        json=payload or {}
    ).json()

# Examples
customer_command('{{customerId}}', 'activate')
customer_command('{{customerId}}', 'reject', {'reason': 'Insufficient documentation'})
customer_command('{{customerId}}', 'assignStaff', {'staffId': 'uuid-of-staff'})
customer_command('{{customerId}}', 'proposeTransfer', {
    'destinationOfficeId': 'uuid-of-branch',
    'transferDate': '2024-06-01',
    'transferNote': 'Customer requested branch change'
})

