package main

import (
    "fmt"
    "net/http"
)

func main() {
    req, _ := http.NewRequest("DELETE", "{{base_url}}/api/v1/customers/{{customerId}}", nil)
    req.Header.Set("Authorization", "Bearer {{access_token}}")
    req.Header.Set("X-Tenant-ID", "{{tenant_id}}")
    resp, _ := new(http.Client).Do(req)
    defer resp.Body.Close()
    fmt.Println(resp.StatusCode) // 204 on success
}

